#!/usr/bin/env bash
# Start the live fixture: prom/prometheus with deterministic backfilled blocks.
#
#   test/fixture/run-prometheus.sh start   # prints the base URL
#   test/fixture/run-prometheus.sh stop
#
# The blocks come from `promtool tsdb create-blocks-from openmetrics` over
# test/fixture/data.om (generated by gen_openmetrics.py), so the 2026-01-01
# 00:00-06:00 UTC window has exact, stable values. Retention is 100y so the
# backfill is never deleted. Native histograms are on, so Prometheus's own
# request-latency histograms are ingested as native histograms.
set -euo pipefail
IMAGE="${PROMETHEUS_IMAGE:-prom/prometheus:v3.5.0}"
NAME="${PROMETHEUS_CONTAINER:-vgi-prometheus-server}"
PORT="${PROMETHEUS_PORT:-19090}"
HERE="$(cd "$(dirname "$0")" && pwd)"
case "${1:-start}" in
  stop) docker rm -f "$NAME" >/dev/null 2>&1 || true; exit 0 ;;
  start) ;;
  *) echo "usage: $0 start|stop"; exit 2 ;;
esac
docker rm -f "$NAME" >/dev/null 2>&1 || true
DATA="$(mktemp -d)"
python3 "$HERE/gen_openmetrics.py" > "$DATA/data.om"
chmod 777 "$DATA"
docker run --rm -v "$DATA:/work" --entrypoint promtool "$IMAGE" \
  tsdb create-blocks-from openmetrics /work/data.om /work/tsdb >/dev/null
chmod -R a+rwX "$DATA"
docker run -d --name "$NAME" -p "127.0.0.1:$PORT:9090" -m 512m \
  -v "$DATA/tsdb:/prometheus" \
  -v "$HERE/prometheus.yml:/etc/prometheus/prometheus.yml:ro" \
  -v "$HERE/rules.yml:/etc/prometheus/rules.yml:ro" \
  "$IMAGE" --config.file=/etc/prometheus/prometheus.yml \
  --storage.tsdb.path=/prometheus --storage.tsdb.retention.time=100y \
  --enable-feature=native-histograms --web.enable-admin-api >/dev/null
for _ in $(seq 1 60); do
  if curl -fsS "http://127.0.0.1:$PORT/-/ready" >/dev/null 2>&1; then
    echo "http://127.0.0.1:$PORT"; exit 0
  fi
  sleep 1
done
docker logs "$NAME" >&2; exit 1
